<script lang="ts">
 import {queueDepth} from '$lib/shared/presentation/queue-context';
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {fieldValidation} from '$lib/shared/presentation/form-validation';
 import {onMount,tick} from 'svelte';
 import type {TeamsGateway} from '../application/teams';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {Team} from '../domain/team';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 let {user,gateway}:{user:Account|null;gateway:TeamsGateway}=$props();const {locale}=useLocale();
 let teams=$state<Team[]>([]),loading=$state(true),busy=$state(false),more=$state(false),error=$state(''),selected=$state(''),reason=$state(''),notice=$state('');
 let inspected=$state<Team|null>(null),teamQuery=$state('');
 const visibleTeams=$derived(teams.filter(team=>[team.name,team.description,team.slug].some(value=>value.toLocaleLowerCase().includes(teamQuery.trim().toLocaleLowerCase()))));
 let inspectionPanel=$state<HTMLElement>();let inspectTrigger:HTMLButtonElement|undefined;
 async function inspect(team:Team,trigger:HTMLButtonElement){if(guard&&!guard.confirmDiscard())return;inspectTrigger=trigger;selected='';reason='';inspected=team;await tick();inspectionPanel?.focus({preventScroll:true});if(window.innerWidth<1000)inspectionPanel?.scrollIntoView({block:'start'});}
 async function closeInspection(){if(guard&&!guard.confirmDiscard())return;inspected=null;selected='';reason='';await tick();if(inspectTrigger?.isConnected)inspectTrigger.focus();}
 let guard=$state<{confirmDiscard():boolean}>();
 const dirty=$derived(selected!==''&&reason.trim()!=='');
 async function load(append=false){const batch=await gateway.pending(append?teams.length:0);teams=append?[...teams,...batch]:batch;more=batch.length===100;}
 async function run(action:()=>Promise<void>){busy=true;error='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{if(user?.role!=='admin'){loading=false;return;}void run(async()=>{try{await load();const depth=queueDepth(new URL(window.location.href));for(let step=1;step<depth&&more;step++)await load(true);const wanted=window.location.hash.replace('#queue-','');if(wanted)inspected=teams.find(team=>team.id===wanted)||null;await tick();if(window.location.hash)document.getElementById(window.location.hash.slice(1))?.scrollIntoView();}finally{loading=false;}});});
</script>
<UnsavedChanges {dirty} bind:this={guard}/>
<svelte:head><title>{text($locale,'Команда өтінімдері','Заявки команд')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={text($locale,'Команда өтінімдері','Заявки команд')} description={text($locale,'Мақұлданған командалар жобалар сұрай алады. Қайтарған кезде себебін жаз.','Одобренные команды смогут запрашивать проекты. При возврате укажи причину.')}/>
{#if user?.role!=='admin'}<p>{text($locale,'Әкімші рұқсаты қажет.','Нужен доступ администратора.')}</p><a class="button primary" href="/login?returnTo=%2Fadmin">{text($locale,'Кіру','Войти')}</a>
{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if loading}<p role="status">{text($locale,'Өтінімдер жүктелуде…','Загружаем заявки…')}</p>{:else}
 <div class="team-tabs"><span>{text($locale,'Өтінімдер','Заявки')} · {teams.length}{more?'+':''}</span></div><div class="team-workbench"><section class="team-list"><label>{text($locale,'Жүктелген командалардан іздеу','Поиск среди загруженных команд')}<input type="search" bind:value={teamQuery} placeholder={text($locale,'Команда атауы','Название команды')}/></label>{#each visibleTeams as team}<article class:chosen={inspected?.id===team.id} id={'queue-'+team.id}><h2>{team.name}</h2><p>{team.description||text($locale,'Сипаттама берілмеген','Описание не указано')}</p><div class="team-row-footer"><span>{text($locale,'Қаралуда','На рассмотрении')}</span><button class="button subtle" disabled={busy} onclick={event=>void inspect(team,event.currentTarget)}>{text($locale,'Өтінімді ашу','Открыть заявку')} →</button></div></article>{:else}<div class="empty-state"><h2>{teamQuery?text($locale,'Команда табылмады','Команды не найдены'):text($locale,'Жаңа өтінім жоқ','Новых заявок нет')}</h2><p>{text($locale,'Жоба өтінімдері бөлек бөлімде қаралады.','Заявки на проекты рассматриваются отдельно.')}</p><a class="button subtle" href="/admin/requests">{text($locale,'Жоба өтінімдері','Заявки на проекты')}</a></div>{/each}</section><aside class="team-inspector" bind:this={inspectionPanel} tabindex="-1" aria-label={text($locale,'Команда өтінімі','Заявка команды')}>{#if inspected}<button class="button subtle inspector-back" disabled={busy} onclick={()=>void closeInspection()}>{text($locale,'Тізімге оралу','Вернуться к списку')}</button>{/if}
 {#each inspected?[inspected]:[] as team}<article><h2>{team.name}</h2><p>{team.description||text($locale,'Сипаттама берілмеген.','Описание не указано.')}</p><small>/teams/{team.slug}</small><div class="actions"><button class="button primary" disabled={busy} onclick={()=>{if(selected===team.id&&guard&&!guard.confirmDiscard())return;void run(async()=>{await gateway.approve(team.id);if(selected===team.id){selected='';reason='';}inspected=null;await load();notice=text($locale,'Команда мақұлданды.','Команда одобрена.');});}}>{text($locale,'Мақұлдау','Одобрить')}</button><button class="button subtle" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected=team.id;reason='';}}>{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</button></div>
 {#if selected===team.id}<form use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();void run(async()=>{await gateway.reject(team.id,reason);selected='';reason='';inspected=null;await load();notice=text($locale,'Өтінім себеппен қайтарылды.','Заявка возвращена с причиной.');});}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} required minlength="8" maxlength="2000" rows="3"></textarea></label><div class="actions"><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button><button type="button" class="button subtle" onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected='';reason='';}}>{text($locale,'Бас тарту','Отмена')}</button></div></form>{/if}
 </article>{/each}
</aside></div>
 {#if more}<button class="button subtle" disabled={busy} onclick={()=>run(()=>load(true))}>{text($locale,'Тағы өтінімдер','Ещё заявки')}</button>{/if}
 {/if}
{/if}
<style>article{max-width:840px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);margin-block:12px;min-width:0}h2{font-size:20px;margin:0}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}small{color:var(--muted)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}form{max-width:640px;margin-top:20px}label{display:grid;gap:8px}.team-tabs{margin-bottom:20px}.team-tabs span{display:inline-flex;align-items:center;min-height:44px;padding:8px 16px;background:var(--raised);color:var(--accent);border-radius:8px;font-size:13px}.team-workbench{display:grid;gap:24px;align-items:start}.team-list,.team-inspector{min-width:0}.team-list>label{font-size:12px;color:var(--muted);margin-bottom:16px}.team-list article{max-width:none;padding:20px 24px;margin:0 0 16px}.team-list h2,.team-inspector h2{font-size:17px}.team-list article.chosen{background:var(--raised);border-color:var(--muted)}.team-list article.chosen h2{color:var(--accent)}.team-list article p{font-size:13px;color:var(--muted);margin:12px 0}.team-row-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.team-row-footer .button{background:none;border-color:transparent;font-size:12px}.team-inspector article{max-width:none;margin:0;padding:24px}.team-inspector p{font-size:13px;color:var(--muted);margin-top:16px}.team-inspector form{margin-top:20px}.team-inspector .actions{gap:8px}.team-inspector .button{font-size:12px}.team-inspector:empty{display:none}@media(min-width:1000px){.team-workbench{grid-template-columns:minmax(0,2fr) minmax(280px,1fr)}.team-workbench:not(:has(.team-inspector article)){grid-template-columns:minmax(0,1fr)}.team-inspector{position:sticky;top:88px}} .inspector-back{margin-bottom:12px}.team-inspector{scroll-margin-top:80px}@media(min-width:1000px){.inspector-back{display:none}}</style>
